import{_ as o,o as r,c as e,ag as s}from"./chunks/framework.D5hoimZQ.js";const c=JSON.parse('{"title":"「少而更好」的工程版：把判据变成可执行的评审清单","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/design/less-but-better-engineering.md","filePath":"topics/design/less-but-better-engineering.md"}'),n={name:"topics/design/less-but-better-engineering.md"};function a(l,t,i,u,g,q){return r(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="「少而更好」的工程版-把判据变成可执行的评审清单" tabindex="-1">「少而更好」的工程版：把判据变成可执行的评审清单 <a class="header-anchor" href="#「少而更好」的工程版-把判据变成可执行的评审清单" aria-label="Permalink to &quot;「少而更好」的工程版：把判据变成可执行的评审清单&quot;">​</a></h1><blockquote><p>来源：本库自建（方法论推演），起点是 <code>topics/design/minimalism-death-of-detail.md</code> 第六节的判据：<strong>less, but better（省略装饰 → 增值）vs less, but cheaper（省略能力 → 只是减值）</strong> 外部事实来源：Nielsen 团队 2017 年扁平化界面实测（见主文档，已核实）；Dieter Rams「设计唯一的原罪是漠视人与人所处的现实」 核实状态：本文中的<strong>工程判据与清单为本库归纳，属方法论主张，不是外部研究结论</strong> —— 已在每节标注 整理日期：2026-09-20</p></blockquote><hr><h2 id="一、为什么设计与工程是同一个问题" tabindex="-1">一、为什么设计与工程是同一个问题 <a class="header-anchor" href="#一、为什么设计与工程是同一个问题" aria-label="Permalink to &quot;一、为什么设计与工程是同一个问题&quot;">​</a></h2><p>主文档里那条判据（&quot;少掉的是装饰，还是能力&quot;）在代码里有一个精确的同构：</p><blockquote><p><strong>任何一处简化，都要问：删掉的这段东西，是&quot;为了看起来专业&quot;而存在的，还是&quot;在别人看不见的地方顶着事&quot;？</strong></p></blockquote><ul><li>前者删掉 → 代码变清楚，维护成本下降，<strong>真收益</strong>；</li><li>后者删掉 → 短期看起来一样，直到某个边界条件出现，<strong>负债开始计息</strong>。</li></ul><p>而且代码比设计更残酷：<strong>设计上省略的东西你能看见（一眼就是少了雕花），代码里省略的东西看不见（没有那个 <code>try</code> 之前，谁也不知道它没用）</strong>。所以工程版需要一个<strong>可执行的</strong>清单，而不是审美直觉。</p><hr><h2 id="二、两类复杂度-一张对照表" tabindex="-1">二、两类复杂度：一张对照表 <a class="header-anchor" href="#二、两类复杂度-一张对照表" aria-label="Permalink to &quot;二、两类复杂度：一张对照表&quot;">​</a></h2><blockquote><p>本表为本库归纳，用于判断&quot;该删哪一类&quot;。</p></blockquote><table tabindex="0"><thead><tr><th></th><th><strong>装饰性复杂度</strong>（该删）</th><th><strong>承载性复杂度</strong>（删了就减值）</th></tr></thead><tbody><tr><td>特征</td><td>为&quot;可能的未来&quot;或&quot;看起来专业&quot;而存在</td><td>为&quot;已经会发生的坏情况&quot;而存在</td></tr><tr><td>典型形态</td><td>过早抽象、投机性泛化（三个接口只实现一个）、永远为 false 的开关、只为对齐而存在的包装层、照搬的设计模式、无人读的注释残骸、抄来的通用工具类</td><td>错误处理与重试、边界与空值、权限与数据校验、日志/指标/追踪、并发与事务、迁移与回滚、测试断言、类型与约束、上手文档与示例</td></tr><tr><td>删掉后的体验</td><td>立刻读得懂，改起来更快</td><td><strong>短期毫无变化</strong>，直到那一天到来</td></tr><tr><td>谁来发现代价</td><td>没人</td><td>下一次线上事故 / 下一个接手的人</td></tr><tr><td>判据</td><td>它服务的是一个<strong>假想的</strong>需求</td><td>它服务的是一个<strong>被验证过的</strong>失败模式</td></tr></tbody></table><p><strong>一句话版本</strong>：装饰性复杂度服务<strong>假想的需求</strong>，承载性复杂度服务<strong>已验证的失败模式</strong>。</p><hr><h2 id="三、六条判据-可直接用于-code-review-架构评审" tabindex="-1">三、六条判据（可直接用于 code review / 架构评审） <a class="header-anchor" href="#三、六条判据-可直接用于-code-review-架构评审" aria-label="Permalink to &quot;三、六条判据（可直接用于 code review / 架构评审）&quot;">​</a></h2><blockquote><p>本库归纳。每条给&quot;怎么问&quot;和&quot;怎么测&quot;。</p></blockquote><h3 id="j1-删除测试-可发现性" tabindex="-1">J1 删除测试（可发现性） <a class="header-anchor" href="#j1-删除测试-可发现性" aria-label="Permalink to &quot;J1 删除测试（可发现性）&quot;">​</a></h3><p><strong>问</strong>：把这段删掉，如果它真的在顶事，多久会被发现？ <strong>测</strong>：不是&quot;会不会崩&quot;，而是&quot;<strong>崩了之后，能不能一眼看出是这里</strong>&quot;。</p><ul><li>删掉就立刻报错 → 它是显式依赖，删了等于改需求（别删）；</li><li>删掉后<strong>沉默地错</strong>（数据慢慢不对、性能慢慢差、某个租户悄悄越权）→ 这是最危险的，<strong>必须保留，而且应该补测试把它变成第一种</strong>。</li></ul><h3 id="j2-恢复成本-不可逆性" tabindex="-1">J2 恢复成本（不可逆性） <a class="header-anchor" href="#j2-恢复成本-不可逆性" aria-label="Permalink to &quot;J2 恢复成本（不可逆性）&quot;">​</a></h3><p><strong>问</strong>：加回来要多久？</p><ul><li>一个 <code>if</code> → 删；</li><li>一段在半夜排障时被逐行读过、加了注释才知道为什么这样写的逻辑 → <strong>加回来的往往不是代码，是那晚的经验</strong>。这类东西的恢复成本通常是原价 10 倍以上。</li></ul><h3 id="j3-收益归属-复杂度转移给了谁" tabindex="-1">J3 收益归属（复杂度转移给了谁） <a class="header-anchor" href="#j3-收益归属-复杂度转移给了谁" aria-label="Permalink to &quot;J3 收益归属（复杂度转移给了谁）&quot;">​</a></h3><p><strong>问</strong>：这个简化让<strong>谁</strong>更省事——写它的我，还是后面调它的别人？ 典型症状：把校验、默认值、错误语义<strong>推给调用方</strong>（&quot;参数不对？那是你自己的问题&quot;）。</p><blockquote><p>这正好是设计上的**&quot;最小冒犯&quot;在工程里的镜像**：为了避免在上游表态（不敢定默认值、不敢定错误语义），把成本转嫁给下一个人。<strong>别人替你付的&quot;少&quot;，不是&quot;少&quot;。</strong></p></blockquote><h3 id="j4-可解释性守恒" tabindex="-1">J4 可解释性守恒 <a class="header-anchor" href="#j4-可解释性守恒" aria-label="Permalink to &quot;J4 可解释性守恒&quot;">​</a></h3><p><strong>问</strong>：简化之后，系统是不是更<strong>不可解释</strong>了？</p><ul><li>观测性（日志/指标/追踪/错误上下文）是最容易被当成&quot;装饰&quot;砍掉、又最贵的承载性复杂度：<strong>它不产生任何功能，但它决定你能不能知道系统在干什么</strong>；</li><li>极简的正确方向是<strong>更少的概念 + 更强的可观测</strong>，不是&quot;更少的眼睛&quot;。</li></ul><h3 id="j5-默认值原则-工程版的-给所有人一张没有特征的脸" tabindex="-1">J5 默认值原则（工程版的&quot;给所有人一张没有特征的脸&quot;） <a class="header-anchor" href="#j5-默认值原则-工程版的-给所有人一张没有特征的脸" aria-label="Permalink to &quot;J5 默认值原则（工程版的&quot;给所有人一张没有特征的脸&quot;）&quot;">​</a></h3><p><strong>问</strong>：这个默认值/默认行为，会被多少个调用方踩到？</p><ul><li>公共接口的默认参数、默认超时、默认重试策略、默认权限、默认字符集 —— <strong>默认值是被最多人使用的那条路径，删一个默认值等于把一个隐形决策推给所有人</strong>；</li><li>与品牌趋同那篇同构：设计上的&quot;中性公约数&quot;提供不了性格，但工程的默认值<strong>必须</strong>提供正确的性格（安全、保守、可回退）。</li></ul><h3 id="j6-推迟-删除" tabindex="-1">J6 推迟 ≠ 删除 <a class="header-anchor" href="#j6-推迟-删除" aria-label="Permalink to &quot;J6 推迟 ≠ 删除&quot;">​</a></h3><p><strong>问</strong>：你说&quot;以后再加&quot;，<strong>什么时候必须加？触发条件写下来了吗？</strong></p><ul><li>把复杂度从今天推迟到未来是<strong>正确</strong>的（这几乎是所有好架构的核心动作）；</li><li>但推迟必须附带<strong>触发条件</strong>（&quot;单表超过 X 行就分表&quot;&quot;日活过 Y 就上缓存&quot;），否则它不是推迟，而是<strong>把复杂度藏起来了</strong>；</li><li>判据：如果没人能说出触发条件，&quot;以后再优化&quot;就是&quot;永远不会&quot;的委婉语。</li></ul><hr><h2 id="四、四个高频误用-都能在现场认出来" tabindex="-1">四、四个高频误用（都能在现场认出来） <a class="header-anchor" href="#四、四个高频误用-都能在现场认出来" aria-label="Permalink to &quot;四、四个高频误用（都能在现场认出来）&quot;">​</a></h2><blockquote><p>本库归纳 + 本库已有文档的实际对应。</p></blockquote><p><strong>① YAGNI 被当成万能删刀</strong> YAGNI（You Aren&#39;t Gonna Need It）的正确对象是<strong>投机性的能力</strong>（假想需求）；被滥用的形态是拿它当借口省略<strong>错误处理与边界</strong>（已验证的失败模式）。分界线就是第二节那张表：<strong>需求是假想的，还是失败模式是已验证过的。</strong></p><p><strong>② 极简依赖的两种结局</strong> 少依赖降低<strong>维护成本</strong>（真实收益：升级冲突、供应链风险、体积）；但把依赖换成自己写的一段实现，是<strong>把外部维护成本转成私有维护成本</strong>。 判据：<strong>这是不是你的核心能力？</strong> 是 → 自己写；不是 → 你在用别人的债务换自己的债务。</p><p><strong>③ 单体 vs 分布式：极简不是落后，是推迟</strong> 分布式架构的本质是<strong>用复杂度买扩展性</strong>。极简（单体）不是&quot;技术落后&quot;，而是<strong>在扩展性还没被需要时不付这笔钱</strong>——前提是 J6（触发条件明确）。没有触发条件的单体不是极简，是赌。</p><p><strong>④ 上下文压缩：省 token（真收益）vs 压掉约束（假极简）</strong> 本库 <code>topics/ai-system-architecture/</code> 里反复出现的主线：省 token 是硬收益。但要分清压掉的是什么——</p><ul><li>压掉<strong>重复的样板与冗余上下文</strong> → 真收益（本库已记录&quot;简洁推理压缩&quot;这类方向）；</li><li>压掉<strong>约束、边界条件、失败案例、安全规则</strong> → 表面省钱，代价是幻觉、越界、不可复现。<strong>被压掉的约束不会消失，它只是从&quot;提示里&quot;搬到&quot;事故报告里&quot;。</strong></li></ul><hr><h2 id="五、与设计侧那次-22-的同构" tabindex="-1">五、与设计侧那次 22% 的同构 <a class="header-anchor" href="#五、与设计侧那次-22-的同构" aria-label="Permalink to &quot;五、与设计侧那次 22% 的同构&quot;">​</a></h2><p>主文档里那条硬数据（<strong>Nielsen 团队 2017：扁平化界面操作平均慢 22%</strong>，已核实）在工程里有一条完全对应的规律：</p><blockquote><p><strong>抽象层次减少 ≠ 认知负荷减少，它可能只是把负荷外部化。</strong></p></blockquote><ul><li>界面：去掉视觉层次 → 用户每次都要重新判断&quot;什么可点&quot;；</li><li>代码：去掉一层抽象/封装 → <strong>每个调用点都要自己懂细节</strong>；</li><li>文档：去掉结构性提示（编号、标题、跳转）→ 读者每次都要重新建立地图。</li><li>结论：<strong>&quot;更少&quot;只有在减少了&quot;必须理解的东西&quot;时才是极简；如果只是把同样的复杂度摊平到更多地方，那是把它藏进了搜索成本。</strong></li></ul><hr><h2 id="六、可贴进评审会的一页清单" tabindex="-1">六、可贴进评审会的一页清单 <a class="header-anchor" href="#六、可贴进评审会的一页清单" aria-label="Permalink to &quot;六、可贴进评审会的一页清单&quot;">​</a></h2><blockquote><p>删除前 3 问（任何&quot;我们来精简一下&quot;之前）：</p></blockquote><ol><li>它服务的是<strong>假想需求</strong>还是<strong>已验证的失败模式</strong>？</li><li>删掉后如果错了，<strong>多久、被谁发现</strong>？</li><li>加回来要多久，<strong>需要谁的经验</strong>？</li></ol><blockquote><p>保留时 3 问（反驳&quot;这东西多余&quot;时）：</p></blockquote><ol start="4"><li>我能不能<strong>用一条测试</strong>把它从&quot;沉默的守护&quot;变成&quot;显式的规则&quot;？（能，就保留并加测试；这正是把承载性复杂度<strong>显性化</strong>）</li><li>它是不是在替<strong>别人</strong>（调用方、运维、下一个接手的人）省事？（是 → 这不是装饰）</li><li>它在班表上体现吗？<strong>没人知道它在顶事的东西，才是最该补文档而不是最该删的。</strong></li></ol><hr><h2 id="七、一句话" tabindex="-1">七、一句话 <a class="header-anchor" href="#七、一句话" aria-label="Permalink to &quot;七、一句话&quot;">​</a></h2><blockquote><p><strong>工程上的&quot;少而更好&quot;，是省略假想的需求； 工程上的&quot;少而更便宜&quot;，是省略已验证的失败模式。 两者的代码看起来一样干净——区别只在，第二次线上事故的时候，谁还记得它曾经存在过。</strong></p></blockquote><hr><p>关键词：极简主义、判据、删冗余、承载性复杂度、装饰性复杂度、YAGNI、复杂度转移、可观测性、默认值、默认值原则、上下文压缩、维护成本、技术债、评审清单</p><p>关联：</p><ul><li><code>topics/design/minimalism-death-of-detail.md</code>：判据的出处（less, but better vs less, but cheaper）+ Nielsen 22% 的原始事实</li><li><code>topics/vibe-coding/index.md</code>：SOP 闭环方法论（正向流程/逆向回滚/数据全生命周期）<strong>正是典型的&quot;承载性复杂度&quot;</strong>——它不产生功能，它保证不出事</li><li><code>topics/ai-system-architecture/</code>：上下文压缩与简洁推理压缩（省 token 的真收益），以及&quot;压缩掉约束&quot;的假极简风险</li><li><code>topics/ai-brain/</code>：知识库同理——不是少存，而是靠关联让每条信息复用（删冗余，不删信息）</li><li><code>topics/quality-products/</code>：克制型极简的工业侧同源（德国制造的&quot;少而更好&quot;）</li></ul>',60)])])}const h=o(n,[["render",a]]);export{c as __pageData,h as default};
